class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count(n: int) -> int:
            if n <= 0:
                return 0
            digits = list(map(int, str(n)))
            m = len(digits)

            # Memoization dictionary
            memo = {}

            def dfs(idx: int, tight: bool, current_sum: int, current_product: int) -> int:
                # Base case: all digits placed
                if idx == m:
                    # A number is beautiful if product % sum == 0
                    # Note: current_sum is always > 0 for positive integers
                    # current_product can be 0 (if any digit was 0)
                    if current_sum > 0 and current_product % current_sum == 0:
                        return 1
                    else:
                        return 0

                state = (idx, tight, current_sum, current_product)
                if state in memo:
                    return memo[state]

                limit = digits[idx] if tight else 9
                res = 0

                for d in range(0, limit + 1):
                    new_tight = tight and (d == limit)
                    new_sum = current_sum + d
                    new_product = current_product * d

                    # Optimization: if current_product is 0, it stays 0
                    # But we still need to track it because 0 % s == 0 is true for s > 0

                    res += dfs(idx + 1, new_tight, new_sum, new_product)

                memo[state] = res
                return res

            # Start DFS: index 0, tight True, sum 0, product 1
            # Note: product starts at 1 because it's multiplicative identity
            return dfs(0, True, 0, 1)

        return count(r) - count(l - 1)

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        total_len = n + m - 1

        # Step 1: Process 'T' constraints to determine forced characters
        forced = [None] * total_len
        for i in range(n):
            if str1[i] == 'T':
                for k in range(m):
                    idx = i + k
                    c = str2[k]
                    if forced[idx] is None:
                        forced[idx] = c
                    elif forced[idx] != c:
                        return ""  # Contradiction in 'T' constraints

        # Step 2: Initialize result array with forced characters
        res = [None] * total_len
        for i in range(total_len):
            if forced[i] is not None:
                res[i] = forced[i]

        # Step 3: Precompute 'F' constraints ending at each index
        f_constraints_ending_at = [[] for _ in range(total_len)]
        for i in range(n):
            if str1[i] == 'F':
                end_index = i + m - 1
                if end_index < total_len:
                    f_constraints_ending_at[end_index].append(i)

        # Step 4: Fill in the remaining positions
        for i in range(total_len):
            if res[i] is None:
                assigned = False
                for c in "abcdefghijklmnopqrstuvwxyz":
                    res[i] = c
                    valid = True
                    for j in f_constraints_ending_at[i]:
                        # Check if the substring res[j:j+m] equals str2
                        # Since m is small, we can do a direct comparison
                        if res[j:j+m] == str2:
                            valid = False
                            break
                    if valid:
                        assigned = True
                        break
                    else:
                        res[i] = None  # backtrack
                if not assigned:
                    return ""
            else:
                # Check if forced character causes any 'F' constraint to be violated
                for j in f_constraints_ending_at[i]:
                    if res[j:j+m] == str2:
                        return ""

        return "".join(res)

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        def manhattan_dist(p1, p2):
            return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

        def get_perimeter_coord(p, side):
            x, y = p
            if y == 0:
                return x
            elif x == side:
                return side + y
            elif y == side:
                return 2 * side + (side - x)
            else:  # x == 0
                return 3 * side + (side - y)

        n = len(points)
        # Sort points by perimeter coordinate
        points_with_pc = []
        for i, p in enumerate(points):
            pc = get_perimeter_coord(p, side)
            points_with_pc.append((pc, i))
        points_with_pc.sort()
        sorted_indices = [idx for _, idx in points_with_pc]
        sorted_points = [points[idx] for idx in sorted_indices]

        # Binary search on the answer
        low, high = 0, 2 * side

        def can_select(mid):
            # Check if we can select k points with pairwise Manhattan distance >= mid
            # Use DFS/backtracking with pruning
            selected = []

            def dfs(start_idx, count):
                if count == k:
                    return True
                # Prune: if remaining points are not enough
                if count + (n - start_idx) < k:
                    return False

                for i in range(start_idx, n):
                    p = sorted_points[i]
                    # Check distance against all selected points
                    valid = True
                    for sel in selected:
                        if manhattan_dist(p, sel) < mid:
                            valid = False
                            break
                    if valid:
                        selected.append(p)
                        if dfs(i + 1, count + 1):
                            return True
                        selected.pop()
                return False

            return dfs(0, 0)

        # Binary search
        ans = 0
        while low <= high:
            mid = (low + high) // 2
            if can_select(mid):
                ans = mid
                low = mid + 1
            else:
                high = mid - 1

        return ans

class Solution:
    def countSubstrings(self, s: str) -> int:
        n = len(s)
        count = 0

        for d in range(1, 10):
            if d == 0:
                continue

            import math
            if math.gcd(10, d) == 1:
                inv10 = pow(10, -1, d)
                freq = [0] * d
                inv_pow10 = 1
                P = 0

                for j in range(n):
                    digit = int(s[j])
                    val = (P * inv_pow10) % d
                    freq[val] += 1

                    P = (P * 10 + digit) % d

                    if digit == d:
                        target = (P * inv_pow10) % d
                        count += freq[target]

                    inv_pow10 = (inv_pow10 * inv10) % d
            else:
                for j in range(n):
                    if int(s[j]) != d:
                        continue
                    num = 0
                    pow10 = 1
                    for i in range(j, -1, -1):
                        digit = int(s[i])
                        num = (digit * pow10 + num) % d
                        pow10 = (pow10 * 10) % d
                        if num == 0:
                            count += 1

        return count

