                    new_units = dp[w - c] + a
                    if new_units > dp[w]:
                        dp[w] = new_units

        # Find minimum w such that dp[w] >= k
        for w in range(X + 1):
            if dp[w] >= k:
                return w

        return float('inf')

    # Check function for binary search
    def check(k):
        c1 = min_calories_for_vitamin(1, k)
        if c1 == float('inf'):
            return False
        c2 = min_calories_for_vitamin(2, k)
        if c2 == float('inf'):
            return False
        c3 = min_calories_for_vitamin(3, k)
        if c3 == float('inf'):
