class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        l = 0
        current_cost = 0
        count = 0

        for r in range(n):
            # When expanding to include nums[r], we need to consider the pair (r-1, r)
            # if r > 0. The cost is max(0, nums[r-1] - nums[r])
            if r > 0:
                if nums[r] < nums[r-1]:
                    current_cost += nums[r-1] - nums[r]

            # If current_cost exceeds k, shrink from the left
            while current_cost > k and l < r:
                # When removing nums[l], we remove the cost associated with the pair (l, l+1)
                # which is max(0, nums[l] - nums[l+1])
                if nums[l+1] < nums[l]:
                    current_cost -= nums[l] - nums[l+1]
                l += 1

            # Now the window [l, r] is valid
            count += (r - l + 1)

        return count

class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        n = len(intervals)
        indexed_intervals = [(l, r, w, i) for i, (l, r, w) in enumerate(intervals)]
        indexed_intervals.sort(key=lambda x: (x[1], x[0], x[3]))

        right_endpoints = sorted(set(x[1] for x in indexed_intervals))
        comp_map = {val: idx + 1 for idx, val in enumerate(right_endpoints)}
        m = len(right_endpoints)

        import bisect

        class BIT:
            def __init__(self, size):
                self.n = size
                self.tree = [None] * (self.n + 1)

            def update(self, i, weight, path):
                while i <= self.n:
                    if self.tree[i] is None:
                        self.tree[i] = (weight, path)
                    else:
                        curr_w, curr_path = self.tree[i]
                        if weight > curr_w or (weight == curr_w and path < curr_path):
                            self.tree[i] = (weight, path)
                    i += i & (-i)

            def query(self, i):
                res = None
                while i > 0:
                    if self.tree[i] is not None:
                        if res is None:
                            res = self.tree[i]
                        else:
                            curr_w, curr_path = self.tree[i]
                            res_w, res_path = res
                            if curr_w > res_w or (curr_w == res_w and curr_path < res_path):
                                res = self.tree[i]
                    i -= i & (-i)
                return res

        bits = [BIT(m) for _ in range(4)]

        for l, r, w, idx in indexed_intervals:
            comp_r = comp_map[r]
            pos = bisect.bisect_left(right_endpoints, l)

            updates = []

            w0, p0 = 0, []
            w1_new = w0 + w
            p1_new = p0 + [idx]
            updates.append((1, w1_new, p1_new))

            res1 = bits[0].query(pos)
            if res1 is not None:
                w1, p1 = res1
                w2_new = w1 + w
                p2_new = p1 + [idx]
                updates.append((2, w2_new, p2_new))

            res2 = bits[1].query(pos)
            if res2 is not None:
                w2, p2 = res2
                w3_new = w2 + w
                p3_new = p2 + [idx]
                updates.append((3, w3_new, p3_new))

            res3 = bits[2].query(pos)
            if res3 is not None:
                w3, p3 = res3
                w4_new = w3 + w
                p4_new = p3 + [idx]
                updates.append((4, w4_new, p4_new))

            for k, weight, path in updates:
                bit_idx = k - 1
                bits[bit_idx].update(comp_r, weight, path)

        best_weight = -1
        best_path = []

        for i in range(4):
            res = bits[i].query(m)
            if res is not None:
                w, p = res
                if w > best_weight:
                    best_weight = w
                    best_path = p
                elif w == best_weight:
                    if p < best_path:
                        best_path = p

        return best_path

import sys

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        M = int(next(iterator))
    except StopIteration:
        return

    # We need to store min_R and min_C. Since N can be up to 10^9, we use dictionaries.
    # min_R[r] stores the maximum Y coordinate of a black cell in row r.
    # min_C[c] stores the maximum X coordinate of a black cell in column c.
    min_R = {}
    min_C = {}

    # Store black and white cells separately for processing
    black_cells = []
    white_cells = []

    for _ in range(M):
        x = int(next(iterator))
        y = int(next(iterator))
        c = next(iterator)

        if c == 'B':
            black_cells.append((x, y))
        else:
            white_cells.append((x, y))

    # Process black cells to determine minimum required thresholds
    for x, y in black_cells:
        # Update min_R for row x
        if x in min_R:
            if y > min_R[x]:
                min_R[x] = y
        else:
            min_R[x] = y

        # Update min_C for column y
        if y in min_C:
            if x > min_C[y]:
                min_C[y] = x
        else:
            min_C[y] = x

    # Process white cells to check consistency
    # For a white cell at (x, y), it must NOT be black.
    # A cell (x, y) is black if y <= min_R[x] AND x <= min_C[y].
    # So it is white if y > min_R[x] OR x > min_C[y].
    # Note: if a row/col has no black cells, min_R[x] or min_C[y] is effectively 0.

    for x, y in white_cells:
        # Get the threshold for row x, default to 0 if not present
        r_threshold = min_R.get(x, 0)
        # Get the threshold for column y, default to 0 if not present
        c_threshold = min_C.get(y, 0)

        # Check if the cell would be black under these thresholds
        # It is black if y <= r_threshold AND x <= c_threshold
        is_black = (y <= r_threshold) and (x <= c_threshold)

        if is_black:
            print("No")
            return

    # If all white cells are consistent
    print("Yes")

